{"content": "// TILE TYPES
const TILE_AIR = 0;
const TILE_DIRT = 1;
const TILE_STONE = 2;
const TILE_GRASS = 3;
const TILE_SAND = 4;
const TILE_CLAY = 5;
const TILE_COPPER = 6;
const TILE_IRON = 7;
const TILE_SILVER = 8;
const TILE_GOLD = 9;
const TILE_WOOD = 10;
const TILE_LEAVES = 11;
const TILE_PLANKS = 12;
const TILE_TORCH = 13;
const TILE_WORKBENCH = 14;
const TILE_FURNACE = 15;
const TILE_ANVIL = 16;
const TILE_CHEST = 17;
const TILE_PLATFORM = 18;
const TILE_COUNT = 19;

// Perlin-style simple noise
function hash(x, y, seed) {
  let h = seed + x * 374761393 + y * 668265263;
  h = (h ^ (h >> 13)) * 1274126177;
  return (h ^ (h >> 16)) & 0x7fffffff;
}

function noise(x, y, seed) {
  return (hash(x, y, seed) % 1000) / 1000;
}

function smoothNoise(x, y, seed) {
  const ix = Math.floor(x), iy = Math.floor(y);
  const fx = x - ix, fy = y - iy;
  const sx = fx * fx * (3 - 2 * fx);
  const sy = fy * fy * (3 - 2 * fy);
  const n00 = noise(ix, iy, seed);
  const n10 = noise(ix + 1, iy, seed);
  const n01 = noise(ix, iy + 1, seed);
  const n11 = noise(ix + 1, iy + 1, seed);
  return n00 * (1 - sx) * (1 - sy) + n10 * sx * (1 - sy) + n01 * (1 - sx) * sy + n11 * sx * sy;
}

function initWorld(config) {
  const W = config.width, H = config.height;
  const seed = config.seed;
  const tiles = [];

  // Generate terrain height map
  const surfaceH = [];
  for (let x = 0; x < W; x++) {
    const baseH = 70 + smoothNoise(x * 0.02, 0, seed) * 30 + smoothNoise(x * 0.005, 100, seed) * 40;
    surfaceH.push(Math.floor(baseH));
  }

  // Initialize tile grid
  for (let x = 0; x < W; x++) {
    tiles[x] = [];
    for (let y = 0; y < H; y++) {
      const sh = surfaceH[x];
      let type = TILE_AIR;
      let wall = 0;
      let isActive = true;

      if (y > sh) {
        const depth = y - sh;
        // Caves
        const caveNoise = smoothNoise(x * 0.08, y * 0.08, seed + 500);
        const caveNoise2 = smoothNoise(x * 0.04, y * 0.06, seed + 600);
        const isCave = caveNoise > 0.55 && caveNoise2 > 0.4;

        if (depth <= 3) {
          type = TILE_DIRT;
          if (y === sh + 1 && depth === 1) type = TILE_GRASS; // grass layer
        } else if (depth <= 25) {
          type = isCave ? TILE_AIR : TILE_DIRT;
        } else if (depth <= 80) {
          type = isCave ? TILE_AIR : TILE_STONE;
        } else if (depth <= 160) {
          type = isCave ? TILE_AIR : TILE_STONE;
          // Hell layer at bottom
          if (y > H - 30) type = isCave ? TILE_AIR : TILE_STONE;
        } else {
          type = TILE_STONE;
        }

        if (isCave && type === TILE_AIR) wall = 1; // background wall in caves
      } else {
        type = TILE_AIR;
        isActive = false;
      }

      if (type === TILE_AIR) isActive = false;

      tiles[x][y] = { type, hp: type === TILE_AIR ? 0 : 100, wall, isActive };
    }
  }

  // Sand patches near surface
  for (let x = 0; x < W; x++) {
    const sh = surfaceH[x];
    if (smoothNoise(x * 0.1, 0, seed + 1000) > 0.65) {
      for (let dy = 0; dy < 4 + Math.floor(smoothNoise(x, 0, seed + 2000) * 4); dy++) {
        const y = sh + 1 + dy;
        if (y < H && tiles[x][y].type === TILE_DIRT) {
          tiles[x][y].type = TILE_SAND;
        }
      }
      // sand surface
      if (sh + 1 < H && tiles[x][sh + 1].type === TILE_GRASS) {
        tiles[x][sh + 1].type = TILE_SAND;
      }
    }
  }

  // Clay patches
  for (let x = 0; x < W; x++) {
    const sh = surfaceH[x];
    if (smoothNoise(x * 0.07, 300, seed + 3000) > 0.7) {
      for (let dy = 3; dy < 7; dy++) {
        const y = sh + dy;
        if (y < H && tiles[x][y].type === TILE_DIRT) {
          tiles[x][y].type = TILE_CLAY;
        }
      }
    }
  }

  // Ore veins
  const ores = [
    { type: TILE_COPPER, depth: 5, freq: 0.03, size: 5 },
    { type: TILE_IRON, depth: 12, freq: 0.025, size: 4 },
    { type: TILE_SILVER, depth: 25, freq: 0.018, size: 3 },
    { type: TILE_GOLD, depth: 45, freq: 0.012, size: 3 }
  ];

  for (const ore of ores) {
    for (let x = 0; x < W; x++) {
      for (let y = surfaceH[x] + ore.depth; y < H - 20; y++) {
        if (tiles[x][y].type === TILE_STONE && smoothNoise(x * 1.5, y * 1.5, seed + ore.type * 1000) > 1 - ore.freq) {
          // Place ore vein
          for (let dx = -1; dx <= 1; dx++) {
            for (let dy = -1; dy <= 1; dy++) {
              const nx = x + dx, ny = y + dy;
              if (nx >= 0 && nx < W && ny >= 0 && ny < H &&
                  (tiles[nx][ny].type === TILE_STONE || tiles[nx][ny].type === TILE_DIRT)) {
                if (Math.random() < 0.7) {
                  tiles[nx][ny].type = ore.type;
                }
              }
            }
          }
        }
      }
    }
  }

  // Trees on surface
  for (let x = 2; x < W - 2; x++) {
    const sh = surfaceH[x];
    const isFlat = Math.abs(surfaceH[x] - surfaceH[x + 1]) <= 1 &&
                   Math.abs(surfaceH[x] - surfaceH[x - 1]) <= 1;
    if (isFlat && tiles[x][sh + 1] && tiles[x][sh + 1].type === TILE_GRASS && Math.random() < 0.18) {
      // Tree trunk
      const treeH = 4 + Math.floor(Math.random() * 4);
      for (let ty = sh - treeH; ty <= sh; ty++) {
        if (ty >= 0 && tiles[x][ty].type === TILE_AIR) {
          tiles[x][ty].type = TILE_WOOD;
          tiles[x][ty].isActive = true;
          tiles[x][ty].hp = 100;
        }
      }
      // Leaves
      for (let lx = x - 2; lx <= x + 2; lx++) {
        for (let ly = sh - treeH - 2; ly <= sh - treeH + 1; ly++) {
          if (lx >= 0 && lx < W && ly >= 0 && ly < H && tiles[lx][ly].type === TILE_AIR) {
            if (Math.abs(lx - x) + Math.abs(ly - (sh - treeH)) < 3 && Math.random() < 0.8) {
              tiles[lx][ly].type = TILE_LEAVES;
              tiles[lx][ly].isActive = true;
              tiles[lx][ly].hp = 40;
            }
          }
        }
      }
    }
  }

  // Ensure spawn area is clear (flat, no trees blocking)
  const spawnX = Math.floor(W / 2);
  let spawnY = surfaceH[spawnX] - 2;
  for (let sx = spawnX - 5; sx <= spawnX + 5; sx++) {
    if (sx >= 0 && sx < W) {
      // Clear trees in spawn area
      for (let sy = surfaceH[sx] - 8; sy <= surfaceH[sx]; sy++) {
        if (sy >= 0 && tiles[sx][sy].type === TILE_WOOD || tiles[sx][sy].type === TILE_LEAVES) {
          tiles[sx][sy].type = TILE_AIR;
          tiles[sx][sy].isActive = false;
          tiles[sx][sy].hp = 0;
        }
      }
      // Flatten surface
      tiles[sx][surfaceH[sx] + 1].type = TILE_GRASS;
      tiles[sx][surfaceH[sx] + 1].isActive = true;
      tiles[sx][surfaceH[sx] + 1].hp = 100;
    }
  }

  // Add some starter chest near spawn
  const chestX = spawnX + 6, chestY = surfaceH[chestX];
  if (chestX < W && chestY > 0 && !tiles[chestX][chestY].isActive) {
    tiles[chestX][chestY].type = TILE_CHEST;
    tiles[chestX][chestY].isActive = true;
    tiles[chestX][chestY].hp = 100;
  }

  return {
    width: W, height: H, tiles,
    spawnX, spawnY,
    seed
  };
}
", "path": "K/frags/InitWorld.js"}

{"content": "function updateInput(raw) {
  const keys = {};
  for (const k of Object.keys(raw.keys)) {
    keys[k] = raw.keys[k];
  }

  // Compute mouse tile position relative to world (caller provides camera offset)
  const mx = raw.mouseX || 0;
  const my = raw.mouseY || 0;

  const tileSize = raw.tileSize || 16;
  const camX = raw.cameraX || 0;
  const camY = raw.cameraY || 0;

  const mouseTileX = Math.floor((mx + camX) / tileSize);
  const mouseTileY = Math.floor((my + camY) / tileSize);

  return {
    keys,
    mouseX: mx,
    mouseY: my,
    mouseLeft: !!raw.mouseLeft,
    mouseRight: !!raw.mouseRight,
    mouseWheel: raw.mouseWheel || 0,
    mouseTileX,
    mouseTileY
  };
}
