TILE_TOOL_POWER[TILE_FURNACE] = 35;
TILE_TOOL_POWER[TILE_ANVIL] = 35;
TILE_TOOL_POWER[TILE_CHEST] = 10;
TILE_TOOL_POWER[TILE_PLATFORM] = 0;

// Enemy definitions
const ENEMY_DEFS = {
  0: {name:'Green Slime', hp:14, damage:6, defense:2, width:14, height:12, ai:'slime', color:'#4caf50'},
  1: {name:'Zombie', hp:45, damage:14, defense:4, width:14, height:24, ai:'walker', color:'#8d6e63'},
  2: {name:'Flying Eye', hp:60, damage:18, defense:6, width:16, height:16, ai:'flyer', color:'#b71c1c'},
  3: {name:'Blue Slime', hp:25, damage:8, defense:3, width:14, height:12, ai:'slime', color:'#2196f3'},
  4: {name:'Skeleton', hp:60, damage:20, defense:8, width:14, height:26, ai:'walker', color:'#e0e0e0'},
  5: {name:'Cave Bat', hp:16, damage:12, defense:2, width:12, height:10, ai:'flyer', color:'#5d4037'},
};

// Physics constants
const GRAVITY = 0.35;
const MAX_FALL_SPEED = 12;
const JUMP_VEL = -8.5;
const MOVE_ACCEL = 0.4;
const MAX_WALK_SPEED = 4.5;
const MAX_AIR_SPEED = 3.5;
const FRICTION = 0.25;
const TILE_SIZE = 16;

function tileSolid(world, tx, ty) {
  if (tx < 0 || tx >= world.width || ty < 0 || ty >= world.height) return true; // borders solid
  const t = world.tiles[tx][ty];
  if (!t || !t.isActive) return false;
  return t.type !== TILE_PLATFORM;
}

function tilePlatform(world, tx, ty) {
  if (tx < 0 || tx >= world.width || ty < 0 || ty >= world.height) return false;
  const t = world.tiles[tx][ty];
  return t && t.isActive && t.type === TILE_PLATFORM;
}

function aabbCollide(x, y, w, h, world) {
  // Check tile collisions, return {collides, tileX, tileY, pushX, pushY}
  const left = Math.floor((x - w/2) / TILE_SIZE);
  const right = Math.floor((x + w/2 - 1) / TILE_SIZE);
  const top = Math.floor((y - h/2) / TILE_SIZE);
  const bottom = Math.floor((y + h/2 - 1) / TILE_SIZE);

  for (let tx = left; tx <= right; tx++) {
    for (let ty = top; ty <= bottom; ty++) {
      if (tileSolid(world, tx, ty)) {
        return {collides:true, tileX:tx, tileY:ty};
      }
    }
  }
  return {collides:false};
}

function aabbCollidePlatform(x, y, w, h, world, vy) {
  // Only collide with platforms when falling down onto them
  if (vy < 0) return {collides:false};
  const left = Math.floor((x - w/2) / TILE_SIZE);
  const right = Math.floor((x + w/2 - 1) / TILE_SIZE);
  const ty = Math.floor((y + h/2 - 1) / TILE_SIZE);

  for (let tx = left; tx <= right; tx++) {
    if (tilePlatform(world, tx, ty)) {
      const platTop = ty * TILE_SIZE;
      const entBot = y + h/2;
      const prevEntBot = (y - vy) + h/2;
      if (prevEntBot <= platTop + 2 && entBot >= platTop - 2) {
        return {collides:true, tileX:tx, tileY:ty};
      }
    }
  }
  return {collides:false};
}

function resolvePhysics(entity, world, isPlayer, input) {
  const w2 = entity.width / 2, h2 = entity.height / 2;

  // Apply gravity
  if (!entity.isOnGround) {
    entity.vy += GRAVITY;
    if (entity.vy > MAX_FALL_SPEED) entity.vy = MAX_FALL_SPEED;
  }

  // Player input
  if (isPlayer && input) {
    let maxSpeed = entity.isOnGround ? MAX_WALK_SPEED : MAX_AIR_SPEED;
    if (input.keys['a'] || input.keys['arrowleft']) {
      entity.vx -= MOVE_ACCEL;
      if (entity.vx < -maxSpeed) entity.vx = -maxSpeed;
      entity.facing = -1;
    }
    if (input.keys['d'] || input.keys['arrowright']) {
      entity.vx += MOVE_ACCEL;
      if (entity.vx > maxSpeed) entity.vx = maxSpeed;
      entity.facing = 1;
    }
    if ((input.keys[' '] || input.keys['space'] || input.keys['w'] || input.keys['arrowup']) && entity.isOnGround && entity.jumpCooldown <= 0) {
      entity.vy = JUMP_VEL;
      entity.isOnGround = false;
      entity.jumpCooldown = 8;
      entity.jumpHeld = 10; // frames of sustained jump
    }
    // Extended jump (hold)
    if (entity.jumpHeld > 0 && (input.keys[' '] || input.keys['space'] || input.keys['w'] || input.keys['arrowup'])) {
      entity.vy -= 0.3;
      entity.jumpHeld--;
    }

    // Platform drop-through
    if ((input.keys['s'] || input.keys['arrowdown']) && entity.isOnGround) {
      // Check if standing on platform
      const tx = Math.floor(entity.x / TILE_SIZE);
      const ty = Math.floor((entity.y + h2) / TILE_SIZE);
      if (tilePlatform(world, tx, ty)) {
        entity.y += 4;
        entity.isOnGround = false;
      }
    }
  }

  if (entity.jumpCooldown > 0) entity.jumpCooldown--;

  // Friction
  if (entity.isOnGround && (!isPlayer || !input || (!input.keys['a'] && !input.keys['d'] && !input.keys['arrowleft'] && !input.keys['arrowright']))) {
    if (entity.vx > 0) entity.vx = Math.max(0, entity.vx - FRICTION);
    else if (entity.vx < 0) entity.vx = Math.min(0, entity.vx + FRICTION);
  }

  // X-axis movement + collision
  entity.x += entity.vx;
  {
    const left = Math.floor((entity.x - w2) / TILE_SIZE);
    const right = Math.floor((entity.x + w2 - 1) / TILE_SIZE);
    const top = Math.floor((entity.y - h2 + 2) / TILE_SIZE);
    const bottom = Math.floor((entity.y + h2 - 3) / TILE_SIZE);
    let collided = false;

    for (let ty = top; ty <= bottom; ty++) {
      for (let tx = left; tx <= right; tx++) {
        if (tileSolid(world, tx, ty)) {
          collided = true;
          // Push out
          const tileCenterX = tx * TILE_SIZE + TILE_SIZE / 2;
          if (entity.vx > 0) {
            entity.x = tx * TILE_SIZE - w2 - 0.01;
          } else if (entity.vx < 0) {
            entity.x = tx * TILE_SIZE + TILE_SIZE + w2 + 0.01;
          }
          entity.vx = 0;
        }
      }
    }
  }

  // Y-axis movement + collision
  entity.isOnGround = false;
  entity.y += entity.vy;
  {
    const left = Math.floor((entity.x - w2 + 2) / TILE_SIZE);
    const right = Math.floor((entity.x + w2 - 3) / TILE_SIZE);
    const top = Math.floor((entity.y - h2) / TILE_SIZE);
    const bottom = Math.floor((entity.y + h2 - 1) / TILE_SIZE);

    for (let tx = left; tx <= right; tx++) {
      for (let ty = top; ty <= bottom; ty++) {
        if (tileSolid(world, tx, ty)) {
          if (entity.vy > 0) {
            entity.y = ty * TILE_SIZE - h2 - 0.01;
            entity.isOnGround = true;
          } else if (entity.vy < 0) {
            entity.y = ty * TILE_SIZE + TILE_SIZE + h2 + 0.01;
          }
          entity.vy = 0;
        }
      }
    }

    // Platform collision
    if (!entity.isOnGround) {
      const platCheck = aabbCollidePlatform(entity.x, entity.y, entity.width, entity.height, world, entity.vy);
      if (platCheck.collides) {
        entity.y = platCheck.tileY * TILE_SIZE - h2 - 0.01;
        entity.vy = 0;
        entity.isOnGround = true;
      }
    }
  }

  // World bounds
  if (entity.x - w2 < 0) { entity.x = w2; entity.vx = 0; }
  if (entity.x + w2 > world.width * TILE_SIZE) { entity.x = world.width * TILE_SIZE - w2; entity.vx = 0; }
  if (entity.y - h2 < 0) { entity.y = h2; entity.vy = 0; }
  if (entity.y + h2 > world.height * TILE_SIZE) {
    entity.y = world.height * TILE_SIZE - h2;
    entity.vy = 0;
    entity.isOnGround = true;
    // Kill if fallen out of world
    if (isPlayer) entity.hp = 0;
  }
}

function addToInventory(inventory, itemId, count) {
  // Try to stack first
  for (let i = 0; i < inventory.length; i++) {
    const slot = inventory[i];
    if (slot && slot.itemId === itemId) {
      const maxStack = (ITEMS[itemId] && ITEMS[itemId].maxStack) || 999;
      const canAdd = maxStack - slot.count;
      const toAdd = Math.min(count, canAdd);
      slot.count += toAdd;
      count -= toAdd;
      if (count <= 0) return true;
    }
  }
  // Then find empty slot
  for (let i = 0; i < inventory.length; i++) {
    if (!inventory[i] || inventory[i].count === 0) {
      const maxStack = (ITEMS[itemId] && ITEMS[itemId].maxStack) || 999;
      const toAdd = Math.min(count, maxStack);
      inventory[i] = {itemId, count: toAdd};
      count -= toAdd;
      if (count <= 0) return true;
    }
  }
  return count <= 0;
}

function breakTile(world, tx, ty, toolPower, particles) {
  if (tx < 0 || tx >= world.width || ty < 0 || ty >= world.height) return null;
  const tile = world.tiles[tx][ty];
  if (!tile || !tile.isActive) return null;

  const required = TILE_TOOL_POWER[tile.type] || 0;
  if (toolPower < required) return null; // Can't break this

  tile.hp -= 10 + toolPower * 0.5;
  if (tile.hp <= 0) {
    // Drop item
    const drops = TILE_DROPS[tile.type];
    const itemId = drops ? drops[0] : null;

    // Particles
    for (let i = 0; i < 6; i++) {
      particles.push({
        x: tx * TILE_SIZE + TILE_SIZE/2 + (Math.random()-0.5)*8,
        y: ty * TILE_SIZE + TILE_SIZE/2 + (Math.random()-0.5)*8,
        vx: (Math.random()-0.5)*3,
        vy: -(Math.random()*4+1),
        life: 20 + Math.random()*20,
        maxLife: 40,
        color: '#999',
        size: 2 + Math.random()*3,
        type: 0
      });
    }

    tile.type = TILE_AIR;
    tile.isActive = false;
    tile.hp = 0;
    tile.wall = tile.wall || 0;
    return itemId;
  }
  return null; // Still breaking
}

function placeTile(world, tx, ty, tileType, player) {
  if (tx < 0 || tx >= world.width || ty < 0 || ty >= world.height) return false;
  if (world.tiles[tx][ty].isActive) return false;

  // Check player overlap
  const px = Math.floor(player.x / TILE_SIZE);
  const py = Math.floor(player.y / TILE_SIZE);
  const pw = Math.ceil(player.width / TILE_SIZE);
  const ph = Math.ceil(player.height / TILE_SIZE);
  if (tx >= px - pw && tx <= px + pw && ty >= py - ph && ty <= py + ph) return false;

  world.tiles[tx][ty].type = tileType;
  world.tiles[tx][ty].isActive = true;
  world.tiles[tx][ty].hp = 100;
  return true;
}

function spawnParticle(particles, x, y, vx, vy, color, size, life) {
  particles.push({x,y,vx,vy,color,size,life,maxLife:life,type:0});
}

// Simple enemy AI
function updateEnemyAI(enemy, player, world, particles) {
  const def = ENEMY_DEFS[enemy.type];
  if (!def) return;

  const dx = player.x - enemy.x;
  const dy = player.y - enemy.y;
  const dist = Math.sqrt(dx*dx + dy*dy);

  enemy.facing = dx > 0 ? 1 : -1;

  if (def.ai === 'slime') {
    // Hop towards player
    if (enemy.isOnGround && dist < 300 && !enemy.ai.jumpTimer) {
      enemy.ai.jumpTimer = 40 + Math.random() * 40;
    }
    if (enemy.ai.jumpTimer) {
      enemy.ai.jumpTimer--;
      if (enemy.ai.jumpTimer === 35 && enemy.isOnGround) {
        enemy.vy = -6 - Math.random() * 3;
        enemy.vx = (dx > 0 ? 1 : -1) * (2 + Math.random() * 2);
        enemy.isOnGround = false;
      }
    }
    if (!enemy.isOnGround) {
      enemy.vx *= 0.98;
    } else {
      enemy.vx *= 0.85;
    }

  } else if (def.ai === 'walker') {
    // Walk towards player
    if (dist < 400) {
      const speed = 1.8;
      if (Math.abs(dx) > 20) {
        enemy.vx += (dx > 0 ? 1 : -1) * 0.1;
        enemy.vx = Math.max(-speed, Math.min(speed, enemy.vx));
      }
    } else {
      // Idle wander
      enemy.vx *= 0.9;
      if (Math.abs(enemy.vx) < 0.1) enemy.vx = (Math.random() - 0.5) * 1;
    }
    // Jump if blocked
    if (enemy.isOnGround && enemy.vx !== 0) {
      const aheadTx = Math.floor((enemy.x + (enemy.vx > 0 ? enemy.width/2 + 4 : -enemy.width/2 - 4)) / TILE_SIZE);
      const aheadTy = Math.floor(enemy.y / TILE_SIZE);
      const blockAhead = tileSolid(world, aheadTx, aheadTy) || tileSolid(world, aheadTx, aheadTy - 1);
      if (blockAhead && enemy.ai.jumpCooldown <= 0) {
        enemy.vy = -7;
        enemy.isOnGround = false;
        enemy.ai.jumpCooldown = 15;
      }
    }
    if (enemy.ai.jumpCooldown > 0) enemy.ai.jumpCooldown--;

  } else if (def.ai === 'flyer') {
    // Hover and swoop
    const targetX = player.x;
    const targetY = player.y - 40;
    const speed = 2.5;
    if (dist < 500) {
      enemy.vx += (targetX - enemy.x) * 0.005;
      enemy.vy += (targetY - enemy.y) * 0.005;
    } else {
      enemy.vx += (Math.sin(enemy.ai.phase || 0) * 0.5);
      enemy.vy += (Math.cos(enemy.ai.phase || 0) * 0.5);
    }
    enemy.vx = Math.max(-speed, Math.min(speed, enemy.vx));
    enemy.vy = Math.max(-speed, Math.min(speed, enemy.vy));
    enemy.ai.phase = (enemy.ai.phase || 0) + 0.02;
  }
}

function updateGame(state) {
  const {world, player, enemies, particles, time, input} = state;
  const tileSize = TILE_SIZE;

  // Advance time
  time.ticks++;
  if (time.ticks >= time.dayLength) {
    time.ticks = 0;
    time.dayNumber++;
    time.isDawn = true;
  }
  time.isDaytime = time.ticks < time.dayLength * 0.55; // ~55% day
  time.isDusk = time.ticks >= time.dayLength * 0.53 && time.ticks < time.dayLength * 0.55;
  time.isDawn = time.ticks < time.dayLength * 0.02;
  time.isBloodMoon = (time.dayNumber > 0 && time.dayNumber % 7 === 0 && !time.isDaytime && Math.random() < 0.005);

  // Player attack cooldown
  if (player.attackCooldown > 0) player.attackCooldown--;
  if (player.immunityTimer > 0) player.immunityTimer--;

  // Player physics
  resolvePhysics(player, world, true, input);

  // Block breaking (left click)
  if (input.mouseLeft && player.attackCooldown <= 0) {
    const selSlot = player.inventory[player.hotbarSlot];
    const selItem = selSlot && selSlot.count > 0 ? ITEMS[selSlot.itemId] : null;

    if (selItem && (selItem.type === 'pickaxe' || selItem.type === 'axe')) {
      const tx = input.mouseTileX;
      const ty = input.mouseTileY;
      const dist = Math.sqrt((tx * tileSize + tileSize/2 - player.x)**2 + (ty * tileSize + tileSize/2 - player.y)**2);
      if (dist < tileSize * 5) {
        const dropId = breakTile(world, tx, ty, selItem.toolPower || 0, particles);
        if (dropId !== null) {
          if (dropId !== undefined) {
            addToInventory(player.inventory, dropId, 1);
          }
          player.attackCooldown = selItem.useTime || 16;
        }
      }
    } else if (selItem && selItem.type === 'sword') {
      // Sword swing - damage nearby enemies
      for (const enemy of enemies) {
        if (enemy.hp <= 0) continue;
        const dx = enemy.x - player.x;
        const dy = enemy.y - player.y;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const swingRange = 35;
        if (dist < swingRange && (player.facing > 0 ? dx > -10 : dx < 10)) {
          const damage = Math.max(1, selItem.damage - enemy.defense * 0.5);
          enemy.hp -= damage;
          enemy.immunityTimer = 10;
          enemy.vx += player.facing * 4;
          enemy.vy -= 2;
          for (let i = 0; i < 4; i++) {
            spawnParticle(particles, enemy.x, enemy.y, (Math.random()-0.5)*3, (Math.random()-0.5)*3, '#ff0', 3, 15);
          }
        }
      }
      player.attackCooldown = selItem.useTime || 20;
    } else {
      // Default: try breaking with hand
      const tx = input.mouseTileX;
      const ty = input.mouseTileY;
      const dist = Math.sqrt((tx * tileSize + tileSize/2 - player.x)**2 + (ty * tileSize + tileSize/2 - player.y)**2);
      if (dist < tileSize * 4) {
        const dropId = breakTile(world, tx, ty, 5, particles);
        if (dropId !== undefined && dropId !== null) {
          addToInventory(player.inventory, dropId, 1);
        }
        player.attackCooldown = 28;
      }
    }
  }

  // Block placing (right click)
  if (input.mouseRight && player.attackCooldown <= 0) {
    const selSlot = player.inventory[player.hotbarSlot];
    const selItem = selSlot && selSlot.count > 0 ? ITEMS[selSlot.itemId] : null;
    if (selItem && selItem.placeTile !== undefined) {
      const tx = input.mouseTileX;
      const ty = input.mouseTileY;
      const dist = Math.sqrt((tx * tileSize + tileSize/2 - player.x)**2 + (ty * tileSize + tileSize/2 - player.y)**2);
      if (dist < tileSize * 5) {
        if (placeTile(world, tx, ty, selItem.placeTile, player)) {
          selSlot.count--;
          if (selSlot.count <= 0) player.inventory[player.hotbarSlot] = null;
          player.attackCooldown = 12;
        }
      }
    }
  }

  // Hotbar switching
  if (input.mouseWheel !== 0) {
    player.hotbarSlot = ((player.hotbarSlot - Math.sign(input.mouseWheel)) + 10) % 10;
  }
  if (input.keys['1']) player.hotbarSlot = 0;
  if (input.keys['2']) player.hotbarSlot = 1;
  if (input.keys['3']) player.hotbarSlot = 2;
  if (input.keys['4']) player.hotbarSlot = 3;
  if (input.keys['5']) player.hotbarSlot = 4;
  if (input.keys['6']) player.hotbarSlot = 5;
  if (input.keys['7']) player.hotbarSlot = 6;
  if (input.keys['8']) player.hotbarSlot = 7;
  if (input.keys['9']) player.hotbarSlot = 8;
  if (input.keys['0']) player.hotbarSlot = 9;

  // Heal potion
  if (input.keys['h'] && player.attackCooldown <= 0) {
    for (let i = 0; i < player.inventory.length; i++) {
      const slot = player.inventory[i];
      if (slot && slot.count > 0) {
        const item = ITEMS[slot.itemId];
        if (item && item.type === 'potion' && item.healAmount) {
          player.hp = Math.min(player.hpMax, player.hp + item.healAmount);
          slot.count--;
          if (slot.count <= 0) player.inventory[i] = null;
          player.attackCooldown = 60; // potion cooldown
          break;
        }
      }
    }
  }

  // Natural HP regen
  if (player.hp < player.hpMax && player.immunityTimer <= 0) {
    const regenRate = player.hpMax / 600;
    player.hp = Math.min(player.hpMax, player.hp + regenRate);
  }

  // Update enemies
  for (const enemy of enemies) {
    if (enemy.hp <= 0) continue;
    if (enemy.immunityTimer > 0) enemy.immunityTimer--;

    // AI
    if (!enemy.ai) enemy.ai = {};
    updateEnemyAI(enemy, player, world, particles);

    // Physics
    const def = ENEMY_DEFS[enemy.type];
    resolvePhysics(enemy, world, false, null);

    // Contact damage to player
    const dx = player.x - enemy.x;
    const dy = player.y - enemy.y;
    const dist = Math.sqrt(dx*dx + dy*dy);
    const contactDist = (player.width + enemy.width) / 2 + 2;
    if (dist < contactDist && player.immunityTimer <= 0) {
      const dmg = Math.max(1, (def ? def.damage : 5) - player.defense * 0.5);
      player.hp -= Math.floor(dmg);
      player.immunityTimer = 30;
      // Knockback player
      player.vx += (dx > 0 ? -1 : 1) * 5;
      player.vy -= 3;
    }
  }

  // Remove dead enemies + drops
  for (let i = enemies.length - 1; i >= 0; i--) {
    if (enemies[i].hp <= 0) {
      // Drop loot
      const def = ENEMY_DEFS[enemies[i].type];
      // Drop coins
      const coinAmt = 5 + Math.floor(Math.random() * 20);
      player.coins += coinAmt;
      // Drop items
      if (def) {
        if (enemies[i].type === 0 || enemies[i].type === 3) {
          // Slimes drop gel
          if (Math.random() < 0.7) addToInventory(player.inventory, 32, 1 + Math.floor(Math.random()*2));
        }
        if (enemies[i].type === 2) {
          if (Math.random() < 0.5) addToInventory(player.inventory, 33, 1);
        }
      }
      // Death particles
      for (let j = 0; j < 8; j++) {
        spawnParticle(particles, enemies[i].x, enemies[i].y,
          (Math.random()-0.5)*4, -(Math.random()*4+1),
          def ? def.color : '#ccc', 3, 20 + Math.random()*15);
      }
      enemies.splice(i, 1);
    }
  }

  // Enemy spawning (delegated to SpawnEnemies via external call)
  // Handled by the game loop calling spawnEnemies separately

  // Update particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.15; // particle gravity
    p.life--;
    if (p.life <= 0) particles.splice(i, 1);
  }

  // Player death check
  if (player.hp <= 0) {
    player.hp = player.hpMax;
    player.coins = Math.floor(player.coins * 0.5);
    player.x = player.spawnX || world.spawnX * tileSize + tileSize/2;
    player.y = player.spawnY || world.spawnY * tileSize + tileSize/2;
    player.vx = 0;
    player.vy = 0;
    player.immunityTimer = 120;
  }

  return {world, player, enemies, particles, time};
}
