{"content": "// Tile colors for rendering
const TILE_COLORS = {};
TILE_COLORS[TILE_AIR] = null;
TILE_COLORS[TILE_DIRT] = '#8B5E3C';
TILE_COLORS[TILE_STONE] = '#808080';
TILE_COLORS[TILE_GRASS] = '#4CAF50';
TILE_COLORS[TILE_SAND] = '#F4D03F';
TILE_COLORS[TILE_CLAY] = '#C0392B';
TILE_COLORS[TILE_COPPER] = '#E67E22';
TILE_COLORS[TILE_IRON] = '#95A5A6';
TILE_COLORS[TILE_SILVER] = '#BDC3C7';
TILE_COLORS[TILE_GOLD] = '#F1C40F';
TILE_COLORS[TILE_WOOD] = '#A0522D';
TILE_COLORS[TILE_LEAVES] = '#2E7D32';
TILE_COLORS[TILE_PLANKS] = '#C49A6C';
TILE_COLORS[TILE_TORCH] = '#FFEB3B';
TILE_COLORS[TILE_WORKBENCH] = '#BCAAA4';
TILE_COLORS[TILE_FURNACE] = '#616161';
TILE_COLORS[TILE_ANVIL] = '#757575';
TILE_COLORS[TILE_CHEST] = '#8D6E63';
TILE_COLORS[TILE_PLATFORM] = '#A1887F';

const SKY_DAY = '#87CEEB';
const SKY_NIGHT = '#1a1a2e';
const SKY_DAWN = '#FF7F50';
const SKY_DUSK = '#FF6347';

function getSkyColor(time) {
  const t = time.ticks / time.dayLength;
  if (time.isDawn) return interpolateColor(SKY_NIGHT, SKY_DAWN, (t % 0.02) / 0.02);
  if (time.isDusk) return interpolateColor(SKY_DUSK, SKY_NIGHT, ((t - 0.53) % 0.02) / 0.02);
  if (time.isDaytime) {
    if (t < 0.1) return interpolateColor(SKY_DAWN, SKY_DAY, t / 0.1);
    if (t > 0.45) return interpolateColor(SKY_DAY, SKY_DUSK, (t - 0.45) / 0.08);
    return SKY_DAY;
  }
  return SKY_NIGHT;
}

function interpolateColor(c1, c2, t) {
  const r1 = parseInt(c1.slice(1,3), 16), g1 = parseInt(c1.slice(3,5), 16), b1 = parseInt(c1.slice(5,7), 16);
  const r2 = parseInt(c2.slice(1,3), 16), g2 = parseInt(c2.slice(3,5), 16), b2 = parseInt(c2.slice(5,7), 16);
  const r = Math.round(r1 + (r2-r1)*Math.max(0,Math.min(1,t)));
  const g = Math.round(g1 + (g2-g1)*Math.max(0,Math.min(1,t)));
  const b = Math.round(b1 + (b2-b1)*Math.max(0,Math.min(1,t)));
  return '#' + [r,g,b].map(v => v.toString(16).padStart(2,'0')).join('');
}

function renderFrame(rs) {
  const {ctx, world, player, enemies, particles, time, input, camera, canvasWidth, canvasHeight} = rs;
  const TILE_SIZE = 16;

  // Clear
  ctx.fillStyle = getSkyColor(time);
  ctx.fillRect(0, 0, canvasWidth, canvasHeight);

  // Stars at night
  if (!time.isDaytime) {
    ctx.fillStyle = '#fff';
    const starOffX = camera.x * 0.1;
    for (let i = 0; i < 80; i++) {
      const sx = ((i * 137 + 50) % canvasWidth + starOffX) % canvasWidth;
      const sy = (i * 73 + 20) % (canvasHeight * 0.6);
      const brightness = 0.3 + 0.7 * Math.abs(Math.sin(time.ticks * 0.01 + i));
      ctx.globalAlpha = brightness;
      ctx.fillRect(sx, sy, 1.5, 1.5);
    }
    ctx.globalAlpha = 1;
  }

  // Sun/Moon
  const dayFrac = time.ticks / time.dayLength;
  if (time.isDaytime) {
    const sunX = canvasWidth * 0.5 + Math.cos(dayFrac * Math.PI * 2) * canvasWidth * 0.4;
    const sunY = canvasHeight * 0.5 - Math.sin(dayFrac * Math.PI * 2) * canvasHeight * 0.35;
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(sunX, sunY, 18, 0, Math.PI * 2);
    ctx.fill();
  } else {
    const moonX = canvasWidth * 0.5 + Math.cos(dayFrac * Math.PI * 2) * canvasWidth * 0.4;
    const moonY = canvasHeight * 0.5 - Math.sin(dayFrac * Math.PI * 2) * canvasHeight * 0.35;
    ctx.fillStyle = '#F5F5DC';
    ctx.beginPath();
    ctx.arc(moonX, moonY, 14, 0, Math.PI * 2);
    ctx.fill();
  }

  // Visible tile range
  const startTX = Math.max(0, Math.floor(camera.x / TILE_SIZE) - 1);
  const endTX = Math.min(world.width - 1, Math.floor((camera.x + canvasWidth) / TILE_SIZE) + 1);
  const startTY = Math.max(0, Math.floor(camera.y / TILE_SIZE) - 1);
  const endTY = Math.min(world.height - 1, Math.floor((camera.y + canvasHeight) / TILE_SIZE) + 1);

  // Render tiles
  for (let tx = startTX; tx <= endTX; tx++) {
    for (let ty = startTY; ty <= endTY; ty++) {
      const tile = world.tiles[tx][ty];
      if (!tile || !tile.isActive) continue;
      const sx = tx * TILE_SIZE - camera.x;
      const sy = ty * TILE_SIZE - camera.y;

      if (sx + TILE_SIZE < 0 || sx > canvasWidth || sy + TILE_SIZE < 0 || sy > canvasHeight) continue;

      const color = TILE_COLORS[tile.type] || '#888';
      ctx.fillStyle = color;
      ctx.fillRect(sx, sy, TILE_SIZE, TILE_SIZE);

      // Subtle edge
      ctx.strokeStyle = 'rgba(0,0,0,0.15)';
      ctx.strokeRect(sx, sy, TILE_SIZE, TILE_SIZE);

      // Special rendering
      if (tile.type === TILE_GRASS) {
        // Green top
        ctx.fillStyle = '#66BB6A';
        ctx.fillRect(sx, sy, TILE_SIZE, 3);
      } else if (tile.type === TILE_TORCH) {
        // Torch flame
        ctx.fillStyle = '#FF9800';
        ctx.fillRect(sx + 6, sy + 2, 4, 6);
        ctx.fillStyle = '#FFEB3B';
        ctx.fillRect(sx + 7, sy + 1, 2, 4);
      } else if (tile.type === TILE_CHEST) {
        ctx.fillStyle = '#FFD700';
        ctx.fillRect(sx + 4, sy + 4, 8, 3);
      }

      // Ore sparkles
      if (tile.type === TILE_COPPER || tile.type === TILE_IRON || tile.type === TILE_SILVER || tile.type === TILE_GOLD) {
        if (Math.random() < 0.05) {
          ctx.fillStyle = 'rgba(255,255,255,0.5)';
          ctx.fillRect(sx + Math.random()*12, sy + Math.random()*12, 2, 2);
        }
      }
    }
  }

  // Render entities (enemies)
  for (const enemy of enemies) {
    if (enemy.hp <= 0) continue;
    const sx = enemy.x - enemy.width/2 - camera.x;
    const sy = enemy.y - enemy.height/2 - camera.y;
    if (sx + enemy.width < 0 || sx > canvasWidth || sy + enemy.height < 0 || sy > canvasHeight) continue;

    const def = ENEMY_DEFS[enemy.type];
    const color = def ? def.color : '#f00';
    const hpFrac = enemy.hp / enemy.hpMax;

    // Body
    ctx.fillStyle = color;
    if (def && def.ai === 'slime') {
      // Round slime shape
      ctx.beginPath();
      ctx.ellipse(sx + enemy.width/2, sy + enemy.height*0.7, enemy.width/2, enemy.height*0.5, 0, 0, Math.PI*2);
      ctx.fill();
    } else if (def && def.ai === 'flyer') {
      // Flying entity
      ctx.fillRect(sx + 2, sy + 2, enemy.width - 4, enemy.height - 4);
      // Wings
      ctx.fillStyle = 'rgba(255,255,255,0.3)';
      const wingFlap = Math.sin(time.ticks * 0.3) * 4;
      ctx.fillRect(sx - 2, sy - 2 + wingFlap, 4, enemy.height/2);
      ctx.fillRect(sx + enemy.width - 2, sy - 2 - wingFlap, 4, enemy.height/2);
    } else {
      // Humanoid
      ctx.fillRect(sx, sy, enemy.width, enemy.height);
      // Head
      ctx.fillRect(sx + 2, sy - 4, enemy.width - 4, 6);
    }

    // Eyes
    ctx.fillStyle = '#fff';
    const eyeX = enemy.facing > 0 ? sx + enemy.width - 5 : sx + 3;
    ctx.fillRect(eyeX, sy + 3, 3, 3);
    ctx.fillStyle = '#000';
    ctx.fillRect(eyeX + 1, sy + 4, 1, 1);

    // HP bar
    if (hpFrac < 1) {
      const barW = enemy.width;
      const barH = 3;
      const barY = sy - 8;
      ctx.fillStyle = '#400';
      ctx.fillRect(sx, barY, barW, barH);
      ctx.fillStyle = hpFrac > 0.5 ? '#0f0' : hpFrac > 0.25 ? '#ff0' : '#f00';
      ctx.fillRect(sx, barY, barW * hpFrac, barH);
    }
  }

  // Render player
  {
    const sx = player.x - player.width/2 - camera.x;
    const sy = player.y - player.height/2 - camera.y;

    // Blink during immunity
    if (player.immunityTimer > 0 && Math.floor(player.immunityTimer / 4) % 2 === 0) {
      ctx.globalAlpha = 0.4;
    }

    // Body
    ctx.fillStyle = '#FFD54F';
    ctx.fillRect(sx + 2, sy + 8, player.width - 4, player.height - 12);
    // Head
    ctx.fillStyle = '#FFCC80';
    ctx.fillRect(sx + 3, sy, player.width - 6, 10);
    // Eyes
    ctx.fillStyle = '#fff';
    const eyeX = player.facing > 0 ? sx + player.width - 6 : sx + 3;
    ctx.fillRect(eyeX, sy + 2, 4, 3);
    ctx.fillStyle = '#000';
    ctx.fillRect(eyeX + 1, sy + 3, 2, 1);
    // Legs
    ctx.fillStyle = '#5D4037';
    ctx.fillRect(sx + 3, sy + player.height - 6, 6, 6);
    ctx.fillRect(sx + player.width - 9, sy + player.height - 6, 6, 6);

    // Held item
    const selSlot = player.inventory[player.hotbarSlot];
    if (selSlot && selSlot.count > 0) {
      const item = ITEMS[selSlot.itemId];
      if (item && item.type === 'sword' && player.attackCooldown > player.useTime * 0.5) {
        // Sword swing arc
        ctx.strokeStyle = '#ccc';
        ctx.lineWidth = 2;
        const swingAngle = player.facing > 0 ? -0.5 : Math.PI + 0.5;
        ctx.beginPath();
        ctx.arc(sx + player.width/2, sy + player.height/2, 20, swingAngle, swingAngle + 1.5);
        ctx.stroke();
      } else if (item && (item.type === 'pickaxe' || item.type === 'axe')) {
        ctx.fillStyle = '#888';
        const hx = player.facing > 0 ? sx + player.width : sx - 6;
        ctx.fillRect(hx, sy + 12, 6, 3);
        ctx.fillRect(hx + 2, sy + 8, 2, 8);
      }
    }

    ctx.globalAlpha = 1;
  }

  // Render particles
  for (const p of particles) {
    const sx = p.x - camera.x;
    const sy = p.y - camera.y;
    if (sx < -4 || sx > canvasWidth+4 || sy < -4 || sy > canvasHeight+4) continue;
    ctx.fillStyle = p.color;
    ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
    ctx.fillRect(sx - p.size/2, sy - p.size/2, p.size, p.size);
  }
  ctx.globalAlpha = 1;

  // Player mining target indicator
  if (input.mouseLeft) {
    const tx = input.mouseTileX;
    const ty = input.mouseTileY;
    const sx = tx * TILE_SIZE - camera.x;
    const sy = ty * TILE_SIZE - camera.y;
    const dist = Math.sqrt((tx * TILE_SIZE + TILE_SIZE/2 - player.x)**2 + (ty * TILE_SIZE + TILE_SIZE/2 - player.y)**2);
    if (dist < TILE_SIZE * 5 && tx >= 0 && tx < world.width && ty >= 0 && ty < world.height && world.tiles[tx][ty].isActive) {
      ctx.strokeStyle = '#ff0';
      ctx.lineWidth = 2;
      ctx.strokeRect(sx, sy, TILE_SIZE, TILE_SIZE);
    }
  }

  // HUD
  // HP Bar
  const hudX = 10, hudY = canvasHeight - 60;
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.fillRect(hudX - 2, hudY - 2, 204, 24);
  ctx.fillStyle = '#600';
  ctx.fillRect(hudX, hudY, 200, 12);
  const hpFrac = player.hp / player.hpMax;
  ctx.fillStyle = hpFrac > 0.5 ? '#0f0' : hpFrac > 0.25 ? '#ff0' : '#f00';
  ctx.fillRect(hudX, hudY, 200 * hpFrac, 12);
  ctx.fillStyle = '#fff';
  ctx.font = '10px monospace';
  ctx.fillText(`HP: ${Math.ceil(player.hp)}/${player.hpMax}`, hudX + 4, hudY + 10);

  // Day/Time
  const timeStr = time.isDaytime ? 'Day' : 'Night';
  ctx.fillText(`${timeStr} ${time.dayNumber}`, canvasWidth - 120, 20);

  // Hotbar
  const barX = canvasWidth / 2 - 160;
  const barY = canvasHeight - 40;
  ctx.fillStyle = 'rgba(0,0,0,0.7)';
  ctx.fillRect(barX - 2, barY - 2, 324, 38);

  for (let i = 0; i < 10; i++) {
    const slotX = barX + i * 32;
    const slot = player.inventory[i];

    if (i === player.hotbarSlot) {
      ctx.strokeStyle = '#FFD700';
      ctx.lineWidth = 2;
      ctx.strokeRect(slotX, barY, 32, 34);
    }

    ctx.strokeStyle = '#555';
    ctx.lineWidth = 1;
    ctx.strokeRect(slotX, barY, 32, 34);

    if (slot && slot.count > 0) {
      const item = ITEMS[slot.itemId];
      if (item) {
        ctx.fillStyle = '#fff';
        ctx.font = '7px monospace';
        ctx.fillText(item.name.substring(0, 8), slotX + 2, barY + 12);
        ctx.fillText(`${slot.count}`, slotX + 2, barY + 28);
      }
    }
  }

  // Coins
  ctx.fillStyle = '#F1C40F';
  ctx.font = '12px monospace';
  ctx.fillText(`Coins: ${player.coins}`, hudX, hudY + 30);
}
