const RECIPES = [
  // result: {itemId, count}, ingredients: [{itemId, count}], station: tileType (0=none)
  {id:0, result:{itemId:14, count:4}, ingredients:[{itemId:5,count:1}], station:0, name:'Wood Planks (x4)'},
