{"content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Simplified Terraria</title>
<style>
* { margin:0; padding:0; box-sizing:border-box; }
body { background:#000; overflow:hidden; display:flex; justify-content:center; align-items:center; height:100vh; }
canvas { display:block; image-rendering:pixelated; cursor:crosshair; }
#crafting { display:none; position:fixed; top:50%; left:50%; transform:translate(-50%,-50%); background:rgba(0,0,0,0.9); color:#fff; padding:16px; border:2px solid #555; max-height:70vh; overflow-y:auto; font:12px monospace; z-index:10; min-width:300px; }
#crafting h3 { margin-bottom:8px; color:#FFD700; }
#crafting .recipe { padding:4px; cursor:pointer; border-bottom:1px solid #333; }
#crafting .recipe:hover { background:rgba(255,255,255,0.1); }
#crafting .recipe .can-craft { color:#4CAF50; }
#crafting .recipe .cannot-craft { color:#F44336; }
#crafting .close { float:right; cursor:pointer; color:#f00; font-size:16px; }
</style>
</head>
<body>
<canvas id="game"></canvas>
<div id="crafting"><span class="close" onclick="document.getElementById('crafting').style.display='none'">&times;</span><h3>Crafting (click to craft)</h3><div id="recipe-list"></div></div>

<script>
// ---- Game orchestration ----
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Input state
const inputRaw = {
  keys: {},
  mouseX: 0, mouseY: 0,
  mouseLeft: false, mouseRight: false,
  mouseWheel: 0,
  canvasRect: null
};

// Event listeners
window.addEventListener('keydown', e => {
  inputRaw.keys[e.key.toLowerCase()] = true;
  if (e.key === 'Escape') {
    const craftDiv = document.getElementById('crafting');
    craftDiv.style.display = craftDiv.style.display === 'block' ? 'none' : 'block';
    if (craftDiv.style.display === 'block') updateCraftingUI();
  }
  if (e.key === 'e' || e.key === 'E') {
    const craftDiv = document.getElementById('crafting');
    craftDiv.style.display = craftDiv.style.display === 'block' ? 'none' : 'block';
    if (craftDiv.style.display === 'block') updateCraftingUI();
  }
  e.preventDefault();
});
window.addEventListener('keyup', e => {
  inputRaw.keys[e.key.toLowerCase()] = false;
  e.preventDefault();
});
canvas.addEventListener('mousemove', e => {
  inputRaw.mouseX = e.clientX;
  inputRaw.mouseY = e.clientY;
});
canvas.addEventListener('mousedown', e => {
  if (e.button === 0) inputRaw.mouseLeft = true;
  if (e.button === 2) inputRaw.mouseRight = true;
  e.preventDefault();
});
canvas.addEventListener('mouseup', e => {
  if (e.button === 0) inputRaw.mouseLeft = false;
  if (e.button === 2) inputRaw.mouseRight = false;
});
canvas.addEventListener('wheel', e => {
  inputRaw.mouseWheel += e.deltaY > 0 ? -1 : 1;
  e.preventDefault();
});
canvas.addEventListener('contextmenu', e => e.preventDefault());
window.addEventListener('resize', () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
});

// Initialize game state
const config = {width:420, height:240, seed: Math.floor(Math.random() * 1000000)};
let world = initWorld(config);
let player = {
  x: world.spawnX * 16 + 8, y: (world.spawnY - 1) * 16,
  vx: 0, vy: 0, width: 16, height: 26,
  facing: 1, hp: 100, hpMax: 100, mp: 20, mpMax: 20,
  defense: 0,
  inventory: new Array(50).fill(null),
  hotbarSlot: 0,
  attackCooldown: 0, immunityTimer: 0,
  isOnGround: false,
  spawnX: world.spawnX * 16 + 8, spawnY: world.spawnY * 16,
  coins: 0,
  jumpCooldown: 0, jumpHeld: 0
};

// Starting items
player.inventory[0] = {itemId:22, count:1}; // Copper Sword
player.inventory[1] = {itemId:20, count:1}; // Copper Pickaxe
player.inventory[2] = {itemId:21, count:1}; // Copper Axe
player.inventory[3] = {itemId:15, count:10}; // Torches

let enemies = [];
let particles = [];
let time = {
  ticks: 0,
  dayNumber: 1,
  dayLength: 14400, // 4 min real time
  isDaytime: true,
  isBloodMoon: false,
  isDawn: false,
  isDusk: false
};
let camera = {x: 0, y: 0};

function updateCraftingUI() {
  const list = document.getElementById('recipe-list');
  // Find nearest station
  let nearbyStation = 0;
  const px = Math.floor(player.x / 16);
  const py = Math.floor(player.y / 16);
  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = -3; dy <= 3; dy++) {
      const tx = px + dx, ty = py + dy;
      if (tx >= 0 && tx < world.width && ty >= 0 && ty < world.height && world.tiles[tx][ty].isActive) {
        const t = world.tiles[tx][ty].type;
        if (t === TILE_WORKBENCH) nearbyStation = Math.max(nearbyStation, TILE_WORKBENCH);
        if (t === TILE_FURNACE) nearbyStation = Math.max(nearbyStation, TILE_FURNACE);
        if (t === TILE_ANVIL) nearbyStation = Math.max(nearbyStation, TILE_ANVIL);
      }
    }
  }

  let html = '';
  for (const recipe of RECIPES) {
    if (recipe.station > nearbyStation) continue;
    // Check if can craft
    const result = craftItem({recipeId: recipe.id, inventory: player.inventory, recipes: RECIPES});
    const canCraft = result.success;
    html += `<div class="recipe" onclick="tryCraft(${recipe.id})" title="${recipe.name}">`;
    html += `<span class="${canCraft ? 'can-craft' : 'cannot-craft'}">${recipe.name}</span>`;
    html += ` <span style="color:#888;font-size:10px">[needs: ${recipe.ingredients.map(i => i.count + 'x ' + (ITEMS[i.itemId] ? ITEMS[i.itemId].name : '?'+i.itemId)).join(', ')}]</span>`;
    html += '</div>';
  }
  list.innerHTML = html || '<div style="color:#888">No recipes available. Place a Work Bench, Furnace, or Anvil nearby.</div>';
}

function tryCraft(recipeId) {
  const result = craftItem({recipeId, inventory: player.inventory, recipes: RECIPES});
  if (result.success) {
    player.inventory = result.inventory;
  }
  updateCraftingUI();
}

// Game loop
function gameLoop() {
  inputRaw.canvasRect = canvas.getBoundingClientRect();

  // Process input
  const inp = updateInput({
    keys: inputRaw.keys,
    mouseX: inputRaw.mouseX,
    mouseY: inputRaw.mouseY,
    mouseLeft: inputRaw.mouseLeft,
    mouseRight: inputRaw.mouseRight,
    mouseWheel: inputRaw.mouseWheel,
    canvasRect: inputRaw.canvasRect,
    tileSize: 16,
    cameraX: camera.x,
    cameraY: camera.y
  });
  // Reset wheel
  inputRaw.mouseWheel = 0;

  // Update game
  const newState = updateGame({world, player, enemies, particles, time, input: inp});
  world = newState.world;
  player = newState.player;
  enemies = newState.enemies;
  particles = newState.particles;
  time = newState.time;

  // Spawn enemies
  const spawnResult = spawnEnemies({time, player, world, enemies, spawnCap: 30});
  enemies = spawnResult.enemies;

  // Update camera (smooth follow)
  const targetCamX = player.x - canvas.width / 2;
  const targetCamY = player.y - canvas.height / 2;
  camera.x += (targetCamX - camera.x) * 0.15;
  camera.y += (targetCamY - camera.y) * 0.15;
  // Clamp camera
  camera.x = Math.max(0, Math.min(world.width * 16 - canvas.width, camera.x));
  camera.y = Math.max(0, Math.min(world.height * 16 - canvas.height, camera.y));

  // Render
  renderFrame({
    ctx, world, player, enemies, particles, time,
    input: inp, camera,
    canvasWidth: canvas.width,
    canvasHeight: canvas.height
  });

  requestAnimationFrame(gameLoop);
}

// Start
